    let ax = locker.stow(locker: ax, load: 9);
    let bay = locker.arrive(label: "bay");
    let bay = locker.stow(locker: bay, load: 30);
    let bay = locker.stow(locker: bay, load: 25);
    let cod = locker.arrive(label: "cod");
