use relay.feed;

pub fn publish(io: Io) -> Result<Unit, Error> uses {Io.write} {
    let frames = feed.frames();
    var total = 0;
    var index = 0;
    while index < frames.len() {
        let value = match frames.get(index: index) {
            Some(frame) => match feed.decode(frame) {
                Ok(number) => number,
                Err(_) => 0,
            },
            None => 0,
        };
        total = total + value;
        index = index + 1;
    }
    feed.emit(io: io, total: total)
}

